import{f as a,D as r,o as s,c as o,k as n,a as t,G as d,ar as l}from"./chunks/framework.HWAOx3Ef.js";const k=JSON.parse('{"title":"Sichtbarkeit des Löschen-Buttons bei Formelementen","description":"","frontmatter":{},"headers":[],"relativePath":"technik/adr/ui/adr006-delete-button-visibility-on-form-elements.md","filePath":"technik/adr/ui/adr006-delete-button-visibility-on-form-elements.md"}'),h={name:"technik/adr/ui/adr006-delete-button-visibility-on-form-elements.md"};function u(c,e,b,m,f,g){const i=r("adr-status");return s(),o("div",null,[e[0]||(e[0]=n("h1",{id:"sichtbarkeit-des-loschen-buttons-bei-formelementen",tabindex:"-1"},[t("Sichtbarkeit des Löschen-Buttons bei Formelementen "),n("a",{class:"header-anchor",href:"#sichtbarkeit-des-loschen-buttons-bei-formelementen","aria-label":'Permalink to "Sichtbarkeit des Löschen-Buttons bei Formelementen"'},"​")],-1)),e[1]||(e[1]=n("h2",{id:"status",tabindex:"-1"},[t("Status "),n("a",{class:"header-anchor",href:"#status","aria-label":'Permalink to "Status"'},"​")],-1)),d(i,{status:"accepted"}),e[2]||(e[2]=l('<h2 id="kontext" tabindex="-1">Kontext <a class="header-anchor" href="#kontext" aria-label="Permalink to &quot;Kontext&quot;">​</a></h2><p>In der Anwendung hatten wir einen Mischbetrieb, bei dem bei Eingabefeldern für Text oder Auswahlfeldern der Button zum Löschen des Inhalts angezeigt wird. Bei einigen war der Button immer sichtbar, bei anderen Elementen nur, wenn man darüber hovered, und einige Elemente nutzen die Möglichkeit nicht.</p><p>In einer Demo hatten wir besprochen, wie wir mit dem Mischbetrieb umgehen wollen.</p><h2 id="entscheidung" tabindex="-1">Entscheidung <a class="header-anchor" href="#entscheidung" aria-label="Permalink to &quot;Entscheidung&quot;">​</a></h2><p>Bei allen Elementen, bei denen die Nutzer*innen einen Wert eintragen, sei es ein Text, ein Datum oder eine Auswahl, soll der Löschbutton immer angezeigt werden, sobald ein Wert eingetragen wurde.</p><h2 id="konsequenzen" tabindex="-1">Konsequenzen <a class="header-anchor" href="#konsequenzen" aria-label="Permalink to &quot;Konsequenzen&quot;">​</a></h2><p>Über die Vuetify-Config wird für alle Komponenten definiert, dass der Löschbutton sichtbar ist und auch sichtbar bleibt, wenn man nicht über das Element hovered.</p><h3 id="positiv" tabindex="-1">Positiv <a class="header-anchor" href="#positiv" aria-label="Permalink to &quot;Positiv&quot;">​</a></h3><p>Weniger individuelle Konfiguration.</p><h3 id="negativ" tabindex="-1">Negativ <a class="header-anchor" href="#negativ" aria-label="Permalink to &quot;Negativ&quot;">​</a></h3><p>Den Nutzer*innen werden mehr Steuerelemente angezeigt. In Bezug auf die Konfiguration gibt es keine negativen Folgen, da bei Bedarf weiterhin eine individuelle Konfiguration erfolgen kann.</p><h2 id="ausnahmen" tabindex="-1">Ausnahmen <a class="header-anchor" href="#ausnahmen" aria-label="Permalink to &quot;Ausnahmen&quot;">​</a></h2><p>Bei der Zulassung der Wahlbriefe gibt es verschiedene Querbezüge zwischen den Feldern. Ein Löschbutton in jedem einzelnen Feld würde eine komplexe Löschlogik erfordern. Zusätzlich wurde die Tabelle mit den vielen Löschbuttons als unübersichtlich empfunden. Nach fachlicher Abstimmung wird hier deshalb auf die Löschbuttons verzichtet.</p>',13))])}const v=a(h,[["render",u]]);export{k as __pageData,v as default};
